-- ============================================================================
-- PARTE 1: SISTEMA DE KEY (JUNKIE) E CARREGAMENTO DA UI
-- ============================================================================

if not game:IsLoaded() then game.Loaded:Wait() end
task.wait(0.2)

local CoreGui = game:GetService("CoreGui")
pcall(function()
    if CoreGui:FindFirstChild("WindUI") then CoreGui.WindUI:Destroy() end
    if getgenv().ZyroWindow then getgenv().ZyroWindow:Close() end
end)

getgenv().ZyroWindow = nil
getgenv().WindUI = nil

local success, WindUI = pcall(function()
    return loadstring(game:HttpGet("https://github.com/Footagesus/WindUI/releases/latest/download/main.lua"))()
end)

if not success or not WindUI then
    warn("ERRO: Não foi possivel carregar a WindUI.")
    return
end

getgenv().WindUI = WindUI

local JunkieSuccess, Junkie = pcall(function()
    return loadstring(game:HttpGet("https://jnkie.com/sdk/library.lua"))()
end)

WindUI:AddTheme({
    Name = "PurpleTech",
    Accent = WindUI:Gradient({["0"] = { Color = Color3.fromHex("#7B2CBF"), Transparency = 0 }, ["100"] = { Color = Color3.fromHex("#9b5de5"), Transparency = 0 }}, { Rotation = 0 }), 
    Background = Color3.fromHex("#0f0f1a"), Outline = Color3.fromHex("#dcd6f7"), Text = Color3.fromHex("#f0f0f0"), Placeholder = Color3.fromHex("#b0a6e2"), Button = Color3.fromHex("#1a1a2e"), Icon = Color3.fromHex("#c77dff"),
})
WindUI:SetTheme("PurpleTech")

WindUI.Services.JunkieService = {
    Name = "Junkie Development",
    Icon = "key",
    Args = { "Service", "Identifier", "Provider" },
    New = function(Service, Identifier, Provider)
        Junkie.service = Service
        Junkie.identifier = Identifier
        Junkie.provider = Provider
        return {
            Verify = function(key)
                local result = Junkie.check_key(key)
                if result and result.valid then
                    getgenv().SCRIPT_KEY = key
                    return true, "Chave válida!" 
                end
                return false, "Chave inválida!" 
            end,
            Copy = function()
                local link = Junkie.get_key_link()
                if link then setclipboard(link) return true end
                return false
            end
        }
    end
}

getgenv().ZyroWindow = WindUI:CreateWindow({
    Title = "ZyroXploit", Icon = "cpu", Author = "Hide The Button! 🔴", Folder = "ZyroHub", Size = UDim2.fromOffset(360, 220), Transparent = true, Theme = "PurpleTech", BackgroundImageTransparency = 0.75, Background = "rbxassetid://71883687533252",
    KeySystem = {
        Note = "Pegue a key clicando em get key e clique em junkie development, após isso cole o link gerado no seu navegador.",
        API = {{ Type = "JunkieService", Service = "ZyroXploit", Identifier = "1015335", Provider = "ZyroXploit" }},
    },
    User = { Enabled = true, Anonymous = false, Callback = function() print("Perfil clicado!") end },
})

WindUI:Notify({ Title = "ZyroXploit", Content = "Carregado!", Duration = 5 })

